/* FODO Website Builder, landing, dashboard, onboarding and template gallery (v32).
   Onboarding: start (AI prompt · guided · template · import · blank) → what you're building → industry (searchable) → business
   details (skip allowed) → goals (multi) → style + colours + fonts → AI sitemap you can edit → generate (real stages from the
   server) → editor. The template gallery filters by industry, style, colour mode, pages, motion and features, supports natural
   search, favourites, recently viewed, device previews and style variations, every template is real, editable data. */
import { renderPage, esc } from "/sites/lib/render.js";
import { TEMPLATES as STATIC } from "/sites/lib/templates.js";
import { INDUSTRIES, SITE_TYPES, GOALS, PROFILES, planSitemap, parsePrompt, findIndustry, designFor } from "/sites/lib/industry.js";
import { STYLES, PALETTES, PAIRINGS, applyStyle, applyPalette } from "/sites/lib/design.js";
