function grid(el, list, o) {
  if (!list.length) { el.innerHTML = '<div class="wb-gempty"><b>No template matches.</b><p class="wb-muted">Try fewer filters, or describe your website and let AI design one for you.</p></div>'; return; }
  el.innerHTML = list.map((t, i) => '<article class="wb-tpl" data-id="' + t.id + '" style="--d:' + Math.min(i, 12) * 40 + 'ms"><div class="wb-tv"><div class="wb-tchrome" aria-hidden="true"><i></i><i></i><i></i></div><iframe tabindex="-1" aria-hidden="true" sandbox="" loading="lazy"></iframe><div class="wb-tov"><button class="wb-btn sm" data-pv="' + t.id + '">Preview</button><button class="wb-btn pri sm" data-use="' + t.id + '">' + (canUse(t) ? "Use template" : "Unlock") + '</button></div>' + (t.featured ? '<span class="wb-tbadge">Featured</span>' : "") + (isFree(t) ? '<span class="wb-tier free">Free</span>' : '<span class="wb-tier' + (canUse(t) ? "" : " lock") + '">' + (canUse(t) ? "Builder" : "🔒 Builder") + "</span>") + '<button class="wb-ib sm wb-fav' + (o.fav.has(t.id) ? " on" : "") + '" data-fav="' + t.id + '" aria-label="Favourite ' + esc(t.name) + '" aria-pressed="' + o.fav.has(t.id) + '">♥</button></div><span><b>' + esc(t.name) + '</b><small>' + esc(t.category) + " · " + t.pages.length + " page" + (t.pages.length === 1 ? "" : "s") + " · " + ((STYLES[styleOf(t)] || {}).name || "Original") + " · " + (t.theme.mode === "dark" ? "Dark" : "Light") + (o.q ? ' · <b class="wb-match">' + matchScore(t, o.q) + "% match</b>" : "") + (USES[t.id] ? " · used " + USES[t.id] + "×" : "") + '</small><small class="wb-feat">' + featuresOf(t).join(" · ") + (t.custom ? " · FODO owner template" : "") + "</small></span></article>").join("");
  const io = "IntersectionObserver" in window ? new IntersectionObserver((es) => es.forEach((e) => { if (!e.isIntersecting) return; io.unobserve(e.target); fill(e.target); }), { rootMargin: "300px" }) : null;
  const fill = (b) => { const t = list.find((x) => x.id === b.dataset.id); b.querySelector("iframe").srcdoc = render(t, "home"); };
  $$(".wb-tpl", el).forEach((b) => { if (io) io.observe(b); else fill(b); });
  $$("[data-pv]", el).forEach((b) => { b.onclick = (e) => { e.stopPropagation(); track("wb_template_previewed", b.dataset.pv); preview(list.find((x) => x.id === b.dataset.pv), o.onUse); }; });
  $$(".wb-tpl", el).forEach((c) => { c.onclick = (e) => { if (e.target.closest("button")) return; track("wb_template_previewed", c.dataset.id); preview(list.find((x) => x.id === c.dataset.id), o.onUse); }; });
  $$("[data-use]", el).forEach((b) => { b.onclick = (e) => { e.stopPropagation(); const t = list.find((x) => x.id === b.dataset.use); seen(t.id); guardUse(t, () => { track("wb_template_selected", t.id); o.onUse(t, null); }); }; });
  $$("[data-fav]", el).forEach((b) => { b.onclick = (e) => { e.stopPropagation(); const id = b.dataset.fav; if (o.fav.has(id)) o.fav.delete(id); else o.fav.add(id); ls.set("wb-fav", [...o.fav]); b.classList.toggle("on"); b.setAttribute("aria-pressed", o.fav.has(id)); }; });
  const fit = () => { const c = el.querySelector(".wb-tv"); if (c && c.clientWidth) el.style.setProperty("--s", (c.clientWidth / 1280).toFixed(4)); }; fit(); if (!el._fit && "ResizeObserver" in window) { el._fit = new ResizeObserver(fit); el._fit.observe(el); }
}
const seen = (id) => ls.set("wb-recent", [id].concat(ls.get("wb-recent", []).filter((x) => x !== id)).slice(0, 12));
/* full preview: desktop / tablet / mobile, every page, style variations, then use it */
export function preview(t, onUse) {
  seen(t.id); let dev = "desktop", page = "home", variant = "";
  const m = document.createElement("div"); m.className = "wb-modal wb-pv"; m.setAttribute("role", "dialog"); m.setAttribute("aria-label", "Template preview");
  m.innerHTML = '<div class="wb-mc wb-big"><div class="wb-pvbar"><b>' + esc(t.name) + '</b><select id="pv-p" aria-label="Page">' + t.pages.map((p) => '<option value="' + p.slug + '">' + esc(p.title) + "</option>").join("") + '</select><div class="wb-dev" role="group" aria-label="Device">' + [["desktop", "▭ Desktop"], ["tablet", "▯ Tablet"], ["mobile", "▮ Mobile"]].map((x) => '<button data-dv="' + x[0] + '" aria-pressed="' + (x[0] === dev) + '">' + x[1] + "</button>").join("") + '</div><span class="wb-sp"></span><button class="wb-btn pri sm" id="pv-use">' + (canUse(t) ? "Use this template" : "🔒 Unlock with Builder") + '</button><button class="wb-ib" data-x aria-label="Close">✕</button></div>' +
    '<div class="wb-pvvar"><span class="wb-muted">Style variation:</span><button class="wb-gchip on" data-var="">Original</button>' + ["minimal", "modern", "luxury", "dark", "editorial", "corporate", "playful", "creative"].map((k) => '<button class="wb-gchip" data-var="' + k + '">' + STYLES[k].name + "</button>").join("") + '</div><div class="wb-pvwrap"><iframe id="pv-if" title="Template preview" sandbox="allow-scripts"></iframe></div><p class="wb-muted">' + t.pages.length + " pages: " + t.pages.map((p) => esc(p.title)).join(", ") + " · Features: " + featuresOf(t).join(", ") + " · Industry: " + esc(t.category) + " · Motion: " + motionOf(t) + " · License: " + esc(t.license.license) + (t.license.client_use_allowed ? " (commercial + client use ✓)" : "") + "</p></div>";
  document.body.appendChild(m);
  const draw = () => { const th = variant ? applyStyle(t.theme, variant, false) : t.theme; $("#pv-if", m).srcdoc = renderPage({ theme: th, settings: { business: { name: t.category } }, pages: t.pages, components: t.components }, page, { base: "#", badge: false }); $("#pv-if", m).className = "pv-" + dev; };
  $$("[data-dv]", m).forEach((b) => { b.onclick = () => { dev = b.dataset.dv; $$("[data-dv]", m).forEach((x) => x.setAttribute("aria-pressed", x === b)); draw(); }; });
  $$("[data-var]", m).forEach((b) => { b.onclick = () => { variant = b.dataset.var; $$("[data-var]", m).forEach((x) => x.classList.toggle("on", x === b)); draw(); }; });
  $("#pv-p", m).onchange = function () { page = this.value; draw(); };
  const close = () => m.remove(); m.addEventListener("click", (e) => { if (e.target === m || e.target.closest("[data-x]")) close(); });
  $("#pv-use", m).onclick = () => { close(); guardUse(t, () => onUse(t, variant || null)); };
  draw();
}

/* ---------- website quick actions (⋯ menu on each website card; the home screen is in wb-home.js) ---------- */
export function siteMenu(root, sites, refresh) {
  $$("[data-more]", root).forEach((b) => { b.onclick = (e) => { e.stopPropagation(); $$(".wb-ctx").forEach((x) => x.remove()); const id = b.dataset.more, s = sites.find((x) => x.id === id), m = document.createElement("div"); m.className = "wb-ctx"; m.setAttribute("role", "menu");
    m.innerHTML = [["open", "✎ Open editor"], ["rename", "Aa Rename"], ["dup", "⧉ Duplicate"], ["share", "🔗 Share preview link"], ["settings", "⚙ Settings"], ["arch", "🗄 Archive"], ["del", "Delete…"]].map((a) => '<button role="menuitem" data-a="' + a[0] + '"' + (a[0] === "del" ? ' class="danger"' : "") + ">" + a[1] + "</button>").join("");
    const r0 = b.getBoundingClientRect(); m.style.left = Math.max(8, Math.min(innerWidth - 230, r0.right - 220)) + "px"; m.style.top = r0.bottom + 6 + "px"; document.body.appendChild(m); const first = m.querySelector("button"); if (first) first.focus(); setTimeout(() => document.addEventListener("click", () => m.remove(), { once: true }), 0);
    m.onkeydown = (ev) => { const bs = [...m.querySelectorAll("button")], i = bs.indexOf(document.activeElement); if (ev.key === "ArrowDown") { ev.preventDefault(); bs[(i + 1) % bs.length].focus(); } if (ev.key === "ArrowUp") { ev.preventDefault(); bs[(i - 1 + bs.length) % bs.length].focus(); } if (ev.key === "Escape") { m.remove(); b.focus(); } };
    m.onclick = async (ev) => { const a = (ev.target.closest("[data-a]") || {}).dataset; if (!a) return; m.remove();
      if (a.a === "open") location.hash = "site=" + id;
      if (a.a === "rename") { const n = prompt("Website name", s.name); if (!n || !n.trim() || n.trim() === s.name) return; const j = await X.api(id); if (!j.ok) return X.toast(j.reason, true); const d = j.site.doc; d.settings = d.settings || {}; d.settings.business = Object.assign({}, d.settings.business, { name: n.trim().slice(0, 80) }); const r = await X.api(id, "PUT", { doc: d, baseRev: j.site.rev, note: "Renamed" }); X.toast(r.ok ? "Renamed." : r.reason, !r.ok); if (r.ok) refresh(); }
      if (a.a === "dup") { const r = await X.api(id + "/duplicate", "POST", {}); X.toast(r.ok ? "Duplicated as “" + r.name + "”" : r.reason, !r.ok); if (r.ok) refresh(); }
      if (a.a === "share") { const r = await X.api(id + "/share", "POST", { days: 7 }); if (!r.ok) return X.toast(r.reason, true); try { await navigator.clipboard.writeText(r.url); X.toast("Preview link copied (valid 7 days)."); } catch (e2) { prompt("Copy this link", r.url); } }
      if (a.a === "settings") location.hash = "site=" + id + "&settings=general";
      if (a.a === "arch") { if (!confirm("Archive “" + s.name + "”? It goes offline; you can restore it from Archived.")) return; const r = await X.api(id + "/archive", "POST", { on: true }); if (r.ok) refresh(); }
      if (a.a === "del") { const i = await X.api(id + "/delete-info"); if (!i.ok) return X.toast(i.reason, true); const w = prompt("Permanently delete “" + i.name + "”" + (i.live ? " (LIVE now)" : "") + "?\n• " + i.pages + " pages, " + i.versions + " versions\n• " + i.formMessages + " form messages, " + i.images + " images\n• " + i.domains + " domains, " + i.products + " products, " + i.orders + " orders, " + i.posts + " posts\nArchive keeps everything instead.\nType DELETE to confirm."); if (w !== "DELETE") return; const r = await X.api(id, "DELETE"); if (r.ok) refresh(); }
    }; }; });
}

