    if (S === "import") h = '<h2>Import an existing website</h2><p class="wb-muted">FODO reads the page structure, navigation, colours and fonts, then builds an <b>original</b> FODO website with the same information architecture.</p><div id="w-imf" class="wb-row"><input class="wb-in" id="w-imu" name="url" placeholder="https://example.com" style="flex:1"><button type="button" id="w-imb" class="wb-btn pri">Analyze</button></div><div id="w-imo"></div>' + nav(true, false);
